					long[] precedingPredicate = { Long.MAX_VALUE, PREDICATE - 1, Long.MAX_VALUE, 7 };
					long[] pattern = { -1, PREDICATE, -1, 7 };
					assertThat(read(fixture.adjacency, txn, managed, order, pattern, precedingPredicate))
							.containsExactlyElementsOf(expected(fixture.quads, order, pattern, precedingPredicate));
					assertThat(read(fixture.adjacency, txn, managed, order, pattern,
							new long[] { 0, PREDICATE + 1, 0, 0 })).isEmpty();
