	private static void assertPageBoundedWork(ReadWork work, PhysicalWork physical) {
		// A sequential two-stream merge needs one page cursor and one delta cursor; allow a directory cursor too.
		// The read budget also allows predecessor positioning, range termination, and every persisted delta.
		long cursorReadBudget = 8 + 4 * (physical.pages() + physical.deltas());
		assertAll(
				() -> assertThat(work.nativeReads.operations().getOrDefault("mdb_cursor_open", 0L))
						.as("cursor lifetime follows the scan, not each singleton row: %s", work)
						.isLessThanOrEqualTo(3),
				() -> assertThat(work.pageDecodes)
						.as("each bounded page is decoded at most once, allowing a predecessor page: %s", work)
						.isLessThanOrEqualTo(physical.pages() + 1),
				() -> assertThat(work.nativeReads.operations().getOrDefault("mdb_cursor_get", 0L))
						.as("native cursor work follows pages and deltas, not logical rows: %s", work)
						.isLessThanOrEqualTo(cursorReadBudget));
	}

	private static List<Quad> read(LmdbPersistentAdjacency adjacency, Txn txn, boolean managed, String order,
			long[] pattern, long[] seek) throws Exception {
		if (managed) {
			try (RecordIterator records = adjacency.scan(txn, pattern[0], pattern[1], pattern[2], pattern[3], true,
					order)) {
				return seekAndCollect(records, seek);
			}
		}
		long stamp = txn.lockManager().readLock();
		try (RecordIterator records = adjacency.scan(txn.get(), pattern[0], pattern[1], pattern[2], pattern[3], true,
				order)) {
			return seekAndCollect(records, seek);
		} finally {
			txn.lockManager().unlockRead(stamp);
		}
	}

	private static List<Quad> seekAndCollect(RecordIterator records, long[] seek) {
		if (seek != null) {
			assertThat(records.seekForward(seek[0], seek[1], seek[2], seek[3])).isTrue();
		}
		return collect(records);
	}

	private static List<Quad> collect(RecordIterator records) {
		List<Quad> result = new ArrayList<>();
		long[] batch = new long[4 * 67];
		int size;
		while ((size = records.fill(batch, 67)) != 0) {
			for (int row = 0; row < size; row++) {
				int offset = row * 4;
				result.add(new Quad(batch[offset], batch[offset + 1], batch[offset + 2], batch[offset + 3]));
			}
		}
		return result;
	}

	private static List<Quad> expected(List<Quad> quads, String order, long[] pattern, long[] seek) {
		Comparator<Quad> comparator = comparator(order);
		Quad minimum = seek == null ? null : new Quad(seek[0], seek[1], seek[2], seek[3]);
		return quads.stream()
				.filter(quad -> (pattern[0] == -1 || pattern[0] == quad.subject())
						&& (pattern[1] == -1 || pattern[1] == quad.predicate())
						&& (pattern[2] == -1 || pattern[2] == quad.object())
						&& (pattern[3] == -1 || pattern[3] == quad.context())
						&& (minimum == null || comparator.compare(quad, minimum) >= 0))
				.sorted(comparator)
				.toList();
	}

	private static Comparator<Quad> comparator(String order) {
		return (left, right) -> {
			for (char field : order.toCharArray()) {
				int compared = Long.compareUnsigned(left.component(field), right.component(field));
				if (compared != 0) {
					return compared;
				}
			}
			return 0;
		};
	}

	private static byte[] key(String order, Quad quad) {
		return TripleIndex.encodeKey(order, quad.subject(), quad.predicate(), quad.object(), quad.context());
	}

	private static Quad quadAt(int ordinal) {
		return new Quad(100 + 2L * ordinal, PREDICATE, 10_000 + 2L * ordinal, ordinal % 3 == 0 ? 7 : 0);
	}

	private static PhysicalWork physicalWork(LmdbPersistentAdjacency adjacency, Txn txn, String order)
			throws Exception {
		long stamp = txn.lockManager().readLock();
		try {
			int plane = order.equals("posc") ? 1 : 0;
			return new PhysicalWork(partitionEntries(txn.get(), adjacency.pagesDbi(), plane),
					partitionEntries(txn.get(), adjacency.deltasDbi(), plane));
		} finally {
			txn.lockManager().unlockRead(stamp);
		}
	}

	private static long partitionEntries(long txn, int database, int plane) throws Exception {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, database, handle));
			long cursor = handle.get(0);
			try {
				MDBVal key = MDBVal.malloc(stack);
				MDBVal value = MDBVal.malloc(stack);
				long count = 0;
				int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
				while (result != MDB_NOTFOUND) {
					E(result);
					ByteBuffer bytes = key.mv_data().order(ByteOrder.BIG_ENDIAN);
					if (bytes.get(0) == plane && bytes.getLong(1) == PREDICATE) {
						count++;
					}
					result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
				}
				return count;
			} finally {
				mdb_cursor_close(cursor);
			}
		}
	}

	private record PhysicalWork(long pages, long deltas) {
	}

	private record Quad(long subject, long predicate, long object, long context) {
		long[] array() {
			return new long[] { subject, predicate, object, context };
		}

		long component(char field) {
			return switch (field) {
			case 's' -> subject;
			case 'p' -> predicate;
			case 'o' -> object;
			case 'c' -> context;
			default -> throw new AssertionError(field);
			};
		}
	}

